// ZOMBI LILE RUNNER - hero voice lines (Mauritian Creole, French TTS).
//
// Each entry maps to exactly one game event (do not play a random line).
//   event: levelStart | jump | chop | cleave | spin
//   text:  the spoken Creole; also used by the speechSynthesis fr-FR fallback
//   data:  loud 22 kHz mono WAV, base64 (works from file://)
//
// To change a line:
//   1. Edit LINES in tools/make_voices.py (text + optional "say" spelling).
//   2. Run:  PIPER=... PIPER_MODEL=... python3 tools/make_voices.py
// If you add a line but leave data as "", the game will use speechSynthesis.
(function () {
  'use strict';
  window.ZR_VOICE_LINES = [
    { event: 'levelStart', text: 'Ala mo vini', data: 'data:audio/wav;base64,' },
    { event: 'jump', text: 'Hep', data: 'data:audio/wav;base64,' },
    { event: 'chop', text: 'Ahhhh', data: 'data:audio/wav;base64,' },
    { event: 'cleave', text: 'Ala to la', data: 'data:audio/wav;base64,' },
    { event: 'spin', text: 'Mort ene fois ta', data: 'data:audio/wav;base64,' }
  ];
})();
